tool_input.command:
@'
import fs from "fs";
import path from "path";
import crypto from "crypto";
const root = path.join(process.env.USERPROFILE, ".openviking/data/viking/default/user/default/memories");
const files = [];
function walk(d){
  for (const e of fs.readdirSync(d, {withFileTypes:true})) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md")) files.push(p);
  }
}
walk(root);
const byBase = new Map();
const byHash = new Map();
const short = [];
const noFields = [];
const thin = [];
for (const f of files) {
  const rel = path.relative(root, f).replace(/\\/g,"/");
  const raw = fs.readFileSync(f, "utf8");
  const body = raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g,"").trim();
  const base = path.basename(f, ".md").toLowerCase();
  if (!byBase.has(base)) byBase.set(base, []);
  byBase.get(base).push(rel);
  const h = crypto.createHash("sha256").update(body).digest("hex").slice(0,16);
  if (!byHash.has(h)) byHash.set(h, []);
  byHash.get(h).push(rel);
  if (body.length < 120) short.push({rel, len: body.length});
  if (!raw.includes("MEMORY_FIELDS")) noFields.push(rel);
  const lines = body.split(/\n/).filter(l=>l.trim()&&!l.startsWith("#"));
  if (body.length < 400 && lines.length < 3) thin.push({rel, len: body.length, lines: lines.length});
}
const dupBase = [...byBase.entries()].filter(([,v])=>v.length>1).sort((a,b)=>b[1].length-a[1].length);
const dupHash = [...byHash.entries()].filter(([,v])=>v.length>1).sort((a,b)=>b[1].length-a[1].length);
console.log("total md:", files.length);
console.log("duplicate basename (different paths):", dupBase.length, "groups");
console.log("duplicate body hash:", dupHash.length, "groups");
console.log("short body <120:", short.length);
console.log("missing MEMORY_FIELDS:", noFields.length);
console.log("thin (<400 chars & <3 content lines):", thin.length);
console.log("\nTop basename dupes:");
for (const [b,v] of dupBase.slice(0,12)) console.log(" ",v.length, b, "->", v.slice(0,3).join(" | "));
console.log("\nTop content dupes:");
for (const [h,v] of dupHash.slice(0,8)) console.log(" ",v.length, h, v[0]);
console.log("\nSample short:", short.slice(0,8).map(x=>x.rel+" ("+x.len+")").join("\n  "));
'@ | Set-Content "$env:TEMP\mem-audit.mjs" -Encoding UTF8; node "$env:TEMP\mem-audit.mjs"

